/bin/bash -lc "python - <<'PY'
import os, json
from bioblend.galaxy import GalaxyInstance
with open(os.environ['GALAXY_API_KEY_FILE']) as fh:
    key=fh.read().strip()
gi=GalaxyInstance(os.environ.get('GALAXY_URL','https://usegalaxy.org'), key=key)
tool_id='toolshed.g2.bx.psu.edu/repos/iuc/bcftools_stats/bcftools_stats/1.22+galaxy0'
t=gi.tools.show_tool(tool_id, io_details=True, link_details=False)

def optval(o):
    if isinstance(o, dict): return o.get('value') or o.get('name') or str(o)[:80]
    if isinstance(o, (list,tuple)): return o[1] if len(o)>1 else (o[0] if o else '')
    return str(o)

def compact(inputs, prefix=''):
    rows=[]
    for inp in inputs:
        name=inp.get('name')
        typ=inp.get('type')
        row={'name':prefix+str(name),'type':typ,'label':inp.get('label'),'value':inp.get('value')}
        if 'options' in inp:
            row['options']=[optval(o) for o in inp.get('options',[])][:30]
        rows.append(row)
        if inp.get('inputs'):
            rows.extend(compact(inp['inputs'], prefix+str(name)+'.'))
        if inp.get('cases'):
            for c in inp['cases']:
                rows.extend(compact(c.get('inputs',[]), prefix+str(name)+'.'))
    return rows
print(json.dumps({'name':t.get('name'),'version':t.get('version'),'inputs':compact(t.get('inputs',[]))}, indent=2))
PY"
